<body>
  <a class="skip-link" href="#support-form">Skip to form</a>
  <main id="main-content">
    <section class="hero" aria-labelledby="page-title">
      <span class="eyebrow">Support</span>
      <h1 id="page-title">Contact our support team</h1>
      <p>Send your details and we’ll get back to you as soon as possible.</p>
    </section>

    <section class="form-card" aria-labelledby="support-form-title">
      <h2 id="support-form-title">Request help</h2>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-describedby="full-name-error">
          <p id="full-name-error" class="field-error" hidden>Error: Enter your full name.</p>
        </div>

        <div class="form-field">
          <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
          <input
            id="email-address"
            name="email"
            type="email"
            autocomplete="email"
            required
            aria-describedby="email-address-error">
          <p id="email-address-error" class="field-error" hidden>Error: Enter a valid email address.</p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            aria-describedby="phone-number-help">
          <p id="phone-number-help" class="field-help">Optional. Use a number like +1 555 123 4567 or 555-123-4567.</p>
        </div>

        <div class="actions">
          <button type="submit">Send message</button>
        </div>

        <p id="form-status" class="success-message" hidden aria-live="polite"></p>
      </form>
    </section>
