       backdrop-filter: blur(10px);
     }

     form {
       display: grid;
       gap: 1rem;
     }

     .form-field {
       display: grid;
       gap: 0.5rem;
     }

     label {
       font-weight: 600;
       color: var(--text);
     }

     .required {
       color: var(--accent-strong);
     }

     input {
       width: 100%;
       min-height: 3rem;
       padding: 0.85rem 1rem;
       border: 1px solid var(--border);
       border-radius: 14px;
       background: var(--panel-2);
       color: var(--text);
       font: inherit;
       transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
     }

     input::placeholder {
       color: #7380a6;
     }

     input:hover {
       border-color: rgba(124, 156, 255, 0.55);
     }

     input:focus-visible,
     button:focus-visible {
       outline: 3px solid rgba(124, 156, 255, 0.88);
       outline-offset: 3px;
     }

     input[aria-invalid="true"] {
       border-color: rgba(255, 123, 138, 0.95);
       box-shadow: 0 0 0 1px rgba(255, 123, 138, 0.28);
     }

     .field-help,
     .field-error {
       margin: 0;
       font-size: 0.92rem;
     }

     .field-help {
       color: var(--muted);
     }

     .field-error {
       color: var(--error);
       font-weight: 500;
     }

     .actions {
       display: flex;
       justify-content: flex-start;
       margin-top: 0.5rem;
     }

     button {
       min-height: 3rem;
       padding: 0.85rem 1.25rem;
       border: 0;
       border-radius: 999px;
       background: linear-gradient(180deg, var(--accent), #5f7fff);
       color: white;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 12px 28px rgba(95, 127, 255, 0.32);
     }

     button:hover {
       filter: brightness(1.04);
     }

     .success-message {
       margin: 1rem 0 0;
       padding: 0.9rem 1rem;
       border-radius: 14px;
       background: rgba(34, 197, 94, 0.12);
       border: 1px solid rgba(34, 197, 94, 0.28);
       color: #b9f2c8;
     }

     @media (max-width: 640px) {
       main {
         padding-top: 4rem;
       }

       .actions {
         width: 100%;
       }

       button {
         width: 100%;
       }
     }

     @media (forced-colors: active) {
       body,
       .form-card,
       input,
       button,
       .skip-link {
         forced-color-adjust: auto;
       }

       input,
       button,
       .skip-link {
         border: 1px solid CanvasText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#support-form">Skip to form</a>
   <main id="main-content">
     <section class="hero" aria-labelledby="page-title">
       <span class="eyebrow">Support</span>
       <h1 id="page-title">Contact our support team</h1>
       <p>Send your details and we’ll get back to you as soon as possible.</p>
     </section>

     <section class="form-card" aria-labelledby="support-form-title">
       <h2 id="support-form-title">Request help</h2>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-describedby="full-name-error">
           <p id="full-name-error" class="field-error" hidden>Error: Enter your full name.</p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
           <input
             id="email-address"
             name="email"
             type="email"
             autocomplete="email"
             required
             aria-describedby="email-address-error">
           <p id="email-address-error" class="field-error" hidden>Error: Enter a valid email address.</p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input
             id="phone-number"
             name="phone"
             type="tel"
             autocomplete="tel"
             aria-describedby="phone-number-help">
           <p id="phone-number-help" class="field-help">Optional. Use a number like +1 555 123 4567 or 555-123-4567.</p>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>

         <p id="form-status" class="success-message" hidden aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("form-status");
     const fields = [
       {
         input: document.getElementById("full-name"),
         error: document.getElementById("full-name-error"),
         validate: (value) => value.trim().length > 0,
       },
       {
         input: document.getElementById("email-address"),
         error: document.getElementById("email-address-error"),
         validate: (value) => value.trim().length > 0 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()),
       },
     ];

     function setErrorState(field, isInvalid) {
       field.input.setAttribute("aria-invalid", String(isInvalid));
       field.error.hidden = !isInvalid;
     }

     function clearStatus() {
       statusMessage.hidden = true;
       statusMessage.textContent = "";
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       clearStatus();

       let firstInvalid = null;

       fields.forEach((field) => {
         const valid = field.validate(field.input.value);
         setErrorState(field, !valid);

         if (!valid && !firstInvalid) {
           firstInvalid = field.input;
         }
       });

       if (firstInvalid) {
         firstInvalid.focus();
         return;
       }

       fields.forEach((field) => setErrorState(field, false));
       statusMessage.textContent = "Thanks — your message is ready to send.";
       statusMessage.hidden = false;
       form.reset();
     });

     fields.forEach((field) => {
       field.input.addEventListener("input", () => {
         if (field.input.getAttribute("aria-invalid") === "true") {
           const valid = field.validate(field.input.value);
           setErrorState(field, !valid);
         }
         clearStatus();
       });
     });
   </script>
 </body>
 </html>

')
